mapper.select:
SELECT a.answer_id AS answerId, a.content AS content, a.is_correct AS isCorrect, a.quiz_id AS quizId FROM quiz_answer a WHERE a.quiz_id IN
#{id}
ORDER BY a.quiz_id, a.answer_id

SELECT EXISTS (
    SELECT 1 FROM place WHERE place_id = #{placeId} AND is_active = TRUE
)

SELECT EXISTS (
    SELECT 1
      FROM place_quiz_info
     WHERE origin_info_id = #{originInfoId}
       AND language       = #{language}
       AND is_active      = TRUE
)

mapper.update:
UPDATE place_quiz_info SET title = #{title}, description = #{description}, difficulty = #{difficulty},
is_active = #{isActive}, deleted_at = CASE WHEN #{isActive} THEN NULL ELSE COALESCE(deleted_at, #{updatedAt}) END,
updated_at = #{updatedAt} WHERE place_quiz_info_id = #{placeQuizInfoId}

UPDATE quiz
   SET question   = #{question},
       updated_at = #{updatedAt}
 WHERE quiz_id    = #{quizId}

UPDATE quiz_answer
   SET content    = #{content},
       is_correct = #{isCorrect}
 WHERE answer_id  = #{answerId}

UPDATE quiz
   SET is_active  = FALSE,
       deleted_at = #{deletedAt},
       updated_at = #{deletedAt}
 WHERE quiz_id    = #{quizId}
   AND is_active  = TRUE

UPDATE place_quiz_info
   SET is_active          = FALSE,
       deleted_at         = #{deletedAt},
       updated_at         = #{deletedAt}
 WHERE place_quiz_info_id = #{placeQuizInfoId}
   AND is_active          = TRUE
